def find_permutation(n, k):
    if k > (n * (n + 1)) // 2:
        return "NO"

    permutation = list(range(1, n + 1))
    max_beauty = (n * (n + 1)) // 2

    if k == max_beauty:
        return "YES\n" + " ".join(map(str, permutation))

    for i in range(n - 1, -1, -1):
        if k <= i + 1:
            permutation = permutation[:i] + list(range(permutation[i] + 1, permutation[i] + k + 1)) + permutation[i + k:]
            return "YES\n" + " ".join(map(str, permutation))
        k -= (i + 1)

    return "NO"

